function waitForFBPixel(callback) {
  var interval = setInterval(function() {
    if (window['fbq']) {
      clearInterval(interval);
      callback();
    }
  }, 200);
}


function waitForGtag(callback) {
  var interval = setInterval(function() {
    if (window['gtag']) {
      clearInterval(interval);
      callback();
    }
  }, 200);
}

function waitForElementExists(el, callback) {
  var interval = setInterval(function() {
    if ($(el).length) {
      clearInterval(interval);
      callback();
    }
  }, 200);
}

